sys_script_include.script:
var HKOHandler = Class.create();
HKOHandler.prototype = {
    initialize: function() {},

    getHKOWeather: function(lang) {
		let hkoHTML = "";

		try {
			var inputs = {};
			inputs['lang'] = lang;
			var result = sn_fd.FlowAPI.getRunner().action('x_snc_duty_travel.get_weather_warning_hko').inForeground().withInputs(inputs).run();
			var outputs = result.getOutputs();
			var response = outputs['response']; // String
			var status = outputs['status']; // String
			var generalsituation = outputs['generalsituation']; // String
			var tcinfo = outputs['tcinfo']; // String
			var firedangerwarning = outputs['firedangerwarning']; // String
			var forecastperiod = outputs['forecastperiod']; // String
			var forecastdesc = outputs['forecastdesc']; // String
			var outlook = outputs['outlook']; // String
			var updatetime = outputs['updatetime']; // String

			var tc_html = '';
			tcinfo ? tc_html = '<b>🌀 Tropical Cyclone:</b><p>' + tcinfo + '</p>' : tc_html = '';

			hkoHTML = 	tc_html + 
						'<b>General Situation:</b>' +
						'<p>' + generalsituation + '</p>' +
						'<b>Forecast:</b>' +
						'<p>' + forecastdesc + '</p>';
			gs.info('DEBUG: '+hkoHTML);

		} catch (ex) {
			var message = ex.getMessage();
			gs.error(message);
		}

		return {
			html: hkoHTML,
			updatedOn: new GlideDateTime().getDisplayValue()
		};
    },

    type: 'HKOHandler'
};
